import random

def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    my_score = 0
    opp_score = 0
    my_cc = 0
    opp_cc = 0
    opp_d_after_my_c = 0
    my_c_count = 0
    opp_c_count = 0
    last_opp = history[-1][1]

    for i, (a, b) in enumerate(history):
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
            my_cc += 1
            opp_cc += 1
        elif a == 'C' and b == 'D':
            opp_score += 5
            if i > 0:
                pass
        elif a == 'D' and b == 'C':
            my_score += 5
        else:
            my_score += 1
            opp_score += 1
        if a == 'C':
            my_c_count += 1
            if b == 'D':
                opp_d_after_my_c += 1
        if b == 'C':
            opp_c_count += 1

    coop_rate = opp_c_count / n if n else 1.0
    my_coop_rate = my_c_count / n if n else 1.0

    if n < 8:
        if n == 1:
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    recent = history[-6:]
    recent_opp_d = sum(1 for _, b in recent if b == 'D')
    recent_opp_c = sum(1 for _, b in recent if b == 'C')
    recent_my_d = sum(1 for a, _ in recent if a == 'D')

    if n >= 12:
        tail = history[-12:]
        tail_opp_d = sum(1 for _, b in tail if b == 'D')
        if tail_opp_d >= 11:
            return 'D'
        if tail_opp_d == 0 and recent_opp_c >= 5:
            return 'C'

    if coop_rate > 0.9 and n > 15:
        return 'C'
    if coop_rate < 0.15:
        return 'D'
    if coop_rate < 0.35 and last_opp == 'D':
        return 'D'

    if recent_opp_d >= 5:
        return 'D'
    if recent_opp_d >= 3 and last_opp == 'D':
        if rng.random() < 0.85:
            return 'D'
    if recent_opp_d == 2 and last_opp == 'D':
        if rng.random() < 0.6:
            return 'D'
    if recent_opp_d == 1 and last_opp == 'D':
        if rng.random() < 0.35:
            return 'D'
    if recent_opp_d == 0:
        if recent_opp_c >= 4:
            return 'C'
        if last_opp == 'C':
            return 'C'

    if n > 40 and coop_rate > 0.7:
        if last_opp == 'D' and rng.random() < 0.3:
            return 'D'
        return 'C'

    if n > 60 and coop_rate > 0.55:
        return 'C'
    if n > 75:
        if coop_rate > 0.4:
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if last_opp == 'D':
        if rng.random() < 0.5:
            return 'D'
        return 'C'
    return 'C'

